package com.ridelink.farepayment.controller; import com.ridelink.farepayment.dto.FareDtos.*;import com.ridelink.farepayment.service.FareService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1") public class FareController {private final FareService s;public FareController(FareService s){this.s=s;}@PostMapping("/fares/estimate")EstimateResponse estimate(@Valid @RequestBody EstimateRequest r){return s.estimate(r);}@PostMapping("/fares/finalize")FareResponse finalizeFare(@Valid @RequestBody FinalizeRequest r){return s.finalize(r);}@PostMapping("/payments")PaymentResponse payment(@Valid @RequestBody PaymentRequest r){return s.payment(r);}@GetMapping("/receipts/{rideId}")ReceiptResponse receipt(@PathVariable String rideId){return s.receipt(rideId);}}
